typedef ap_fixed<16,5> data_t;
// Production arithmetic revision 2: persistent wide sums.
typedef ap_fixed<64,42,AP_TRN,AP_WRAP> acc_t;
static const int FB_ACC_BITS = 64;
static const int FB_ACC_FRAC = 22;
static acc_t fb_from_code(ap_int<64> code) {
    acc_t result; result.range(63,0) = code; return result;
}
static ap_int<64> fb_code(acc_t x) { return x.range(63,0); }
static acc_t fb_div(acc_t a, acc_t b) {
    assert(b != 0);
    ap_int<128> numerator = fb_code(a);
    numerator <<= 22;
    ap_int<128> denominator = fb_code(b);
    ap_int<128> q = numerator / denominator;
    if ((numerator % denominator) != 0 && ((numerator < 0) != (denominator < 0))) --q;
    return fb_from_code(q);
}
static acc_t fb_sqrt(acc_t x) {
    assert(x >= 0);
    ap_uint<128> value = fb_code(x);
    value <<= 22;
    ap_uint<128> remainder = value, root = 0;
    ap_uint<128> bit = ap_uint<128>(1) << 126;
    for (int i=0; i<64; ++i) {
        if (remainder >= root + bit) { remainder -= root + bit; root = (root >> 1) + bit; }
        else root >>= 1;
        bit >>= 2;
    }
    if (value - root * root > root) ++root;
    return fb_from_code(root);
}
